
let produtos = JSON.parse(
    localStorage.getItem("produtos") || "[]"
    );

    const form = document.getElementById("formProduto");

    function salvarProdutos() {
        localStorage.setItem(
                "produtos",
                        JSON.stringify(produtos)
                            );
                            }

                            function listarProdutos() {
                                const tabela = document.getElementById("listaProdutos");

                                    tabela.innerHTML = "";

                                        let totalEstoque = 0;

                                            produtos.forEach((produto, indice) => {
                                                    const total = produto.quantidade * produto.valor;

                                                            totalEstoque += total;

                                                                    const linha = document.createElement("tr");

                                                                            linha.innerHTML = `
                                                                                        <td>${produto.codigo}</td>
                                                                                                    <td>${produto.descricao}</td>
                                                                                                                <td>${produto.quantidade}</td>
                                                                                                                            <td>${produto.valor.toLocaleString("pt-BR", {
                                                                                                                                            style: "currency",
                                                                                                                                                            currency: "BRL"
                                                                                                                                                                        })}</td>
                                                                                                                                                                                    <td>${total.toLocaleString("pt-BR", {
                                                                                                                                                                                                    style: "currency",
                                                                                                                                                                                                                    currency: "BRL"
                                                                                                                                                                                                                                })}</td>
                                                                                                                                                                                                                                            <td>
                                                                                                                                                                                                                                                            <button onclick="alterarValor(${indice})">
                                                                                                                                                                                                                                                                                Alterar valor
                                                                                                                                                                                                                                                                                                </button>

                                                                                                                                                                                                                                                                                                                <button onclick="alterarQuantidade(${indice})">
                                                                                                                                                                                                                                                                                                                                    Alterar quantidade
                                                                                                                                                                                                                                                                                                                                                    </button>

                                                                                                                                                                                                                                                                                                                                                                    <button onclick="excluirProduto(${indice})">
                                                                                                                                                                                                                                                                                                                                                                                        Excluir
                                                                                                                                                                                                                                                                                                                                                                                                        </button>
                                                                                                                                                                                                                                                                                                                                                                                                                    </td>
                                                                                                                                                                                                                                                                                                                                                                                                                            `;

                                                                                                                                                                                                                                                                                                                                                                                                                                    tabela.appendChild(linha);
                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("totalEstoque").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Valor total do estoque: " +
                                                                                                                                                                                                                                                                                                                                                                                                                                                            totalEstoque.toLocaleString("pt-BR", {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        style: "currency",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    currency: "BRL"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Cadastrar produto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            form.addEventListener("submit", function(event) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                event.preventDefault();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const codigo = document.getElementById("codigo").value;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const descricao = document.getElementById("descricao").value;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const quantidade = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("quantidade").value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const valor = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("valor").value
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (produtos.some(p => p.codigo === codigo)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    alert("Esse código já está cadastrado!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const produto = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            codigo: codigo,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    descricao: descricao,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            quantidade: quantidade,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    valor: valor
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            produtos.push(produto);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                salvarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        form.reset();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alert("Produto cadastrado com sucesso!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Alterar valor do produto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function alterarValor(indice) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const novoValor = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        prompt("Digite o novo valor do produto:")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!Number.isFinite(novoValor) || novoValor < 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alert("Valor inválido!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        produtos[indice].valor = novoValor;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            salvarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    alert("Valor alterado com sucesso!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Alterar quantidade do produto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function alterarQuantidade(indice) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const novaQuantidade = Number(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                prompt("Digite a nova quantidade:")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                !Number.isInteger(novaQuantidade) ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        novaQuantidade < 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    alert("Quantidade inválida!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    produtos[indice].quantidade = novaQuantidade;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        salvarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Quantidade alterada com sucesso!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Excluir produto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function excluirProduto(indice) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const confirmar = confirm(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Deseja excluir este produto?"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (confirmar) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            produtos.splice(indice, 1);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    salvarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            listarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Mostrar produtos ao abrir o sistema
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                listarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                